def transform_with_priority(grid):
    """Transform each cell to 3x3 pattern, with priority from earlier source cells"""
    h, w = len(grid), len(grid[0])
    out = [[None]*9 for _ in range(9)]

    for r_in in range(h):
        for c_in in range(w):
            val = grid[r_in][c_in]
            if val == 0:
                continue

            start_r, end_r = r_in*3, (r_in+1)*3
            start_c, end_c = c_in*3, (c_in+1)*3

            # Apply pattern: corners and midpoints of first/last rows get value
            for dr in range(3):
                for dc in range(3):
                    rr, cc = start_r + dr, start_c + dc
                    if (dr == 0 or dr == 2) and (dc == 0 or dc == 2):
                        if out[rr][cc] is None:
                            out[rr][cc] = val

    # Fill remaining with 0
    return [[out[r][c] if out[r][c] is not None else 0 for c in range(9)] for r in range(9)]

# Test input
g_test_in = [
    [0, 0, 3],
    [3, 3, 0],
    [0, 3, 0]
]

test_result = transform_with_priority(g_test_in)

print("Test result:")
for row in test_result: print(row)

import json
print(f"\nJSON submission: {json.dumps(test_result)}")
